package main

import (
	"bufio"
	"fmt"
	"os"
)

func modPow(base, exp, mod int64) int64 {
	result := int64(1)
	base %= mod
	for exp > 0 {
		if exp&1 == 1 {
			result = result * base % mod
		}
		base = base * base % mod
		exp >>= 1
	}
	return result
}

func multiplicativeOrder(a, p int64) int64 {
	order := p - 1
	temp := p - 1
	factors := make([]int64, 0)

	for q := int64(2); q*q <= temp; q++ {
		if temp%q == 0 {
			factors = append(factors, q)
			for temp%q == 0 {
				temp /= q
			}
		}
	}
	if temp > 1 {
		factors = append(factors, temp)
	}

	for _, q := range factors {
		for order%q == 0 && modPow(a, order/q, p) == 1 {
			order /= q
		}
	}
	return order
}

func main() {
	in := bufio.NewReader(os.Stdin)
	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	var a, b, p, x int64
	fmt.Fscan(in, &a, &b, &p, &x)

	order := multiplicativeOrder(a, p)
	period := p * order

	answer := (x / period) * order
	remainder := x % period

	inverseA := modPow(a, p-2, p)
	c := b

	for k := int64(0); k < order; k++ {
		t := (k - c) % order
		if t < 0 {
			t += order
		}
		n := c + p*t
		if n <= remainder {
			answer++
		}
		c = c * inverseA % p
	}

	fmt.Fprintln(out, answer)
}

