package main

import (
	"bufio"
	"fmt"
	"os"
)

func modPow(a, e, mod int64) int64 {
	result := int64(1)
	for e > 0 {
		if e&1 == 1 {
			result = result * a % mod
		}
		a = a * a % mod
		e >>= 1
	}
	return result
}

func main() {
	in := bufio.NewReader(os.Stdin)
	var a, b, p, x int64
	fmt.Fscan(in, &a, &b, &p, &x)

	order := int64(1)
	power := a % p
	for power != 1 {
		power = power * a % p
		order++
	}

	invA := modPow(a, p-2, p)
	invOrder := modPow(order%p, p-2, p)
	invPower := invA
	period := p * order

	var answer int64
	for r := int64(1); r <= order; r++ {
		c := b * invPower % p
		delta := (c - r%p + p) % p
		k := delta * invOrder % p
		n0 := r + order*k

		if n0 <= x {
			answer += (x-n0)/period + 1
		}

		invPower = invPower * invA % p
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, answer)
}

